#!/usr/bin/env node
/**
 * Regenerates packages/database-types/src/database.types.ts from the running
 * local Supabase database.
 *
 * Checklist item: "Database types are generated by script, not hand-written."
 * Run this after every migration, and commit the result — CI diffs the
 * committed file against a freshly generated one to catch drift.
 *
 *   npm run db:types
 */

import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = join(repoRoot, 'packages/database-types/src/database.types.ts');

const BANNER = `/**
 * GENERATED FILE — DO NOT EDIT.
 *
 * Produced by \`npm run db:types\` from the local Supabase schema.
 * To change anything here, edit a migration in supabase/migrations/ and rerun.
 */

`;

let generated;
try {
  generated = execFileSync(
    'npx',
    ['supabase', 'gen', 'types', 'typescript', '--local', '--schema', 'public'],
    {
      cwd: repoRoot,
      encoding: 'utf8',
      maxBuffer: 32 * 1024 * 1024,
      stdio: ['ignore', 'pipe', 'inherit'],
    },
  );
} catch (error) {
  console.error('\nCould not generate types. Is local Supabase running?');
  console.error('  npm run db:start\n');
  process.exit(error.status ?? 1);
}

if (!generated.includes('export type Database')) {
  console.error('\nUnexpected generator output — no Database type found. Refusing to write.');
  process.exit(1);
}

mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, BANNER + generated, 'utf8');

console.log(`Wrote ${outputPath.replace(`${repoRoot}/`, '')} (${generated.length} bytes)`);
